      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks opened a new regime of precision measurement, with implications for fundamental tests, timekeeping, and applications of accurate clocks.",
        "attribution": "Katori's lattice approach and Ye's independent experimental development are both central to the invention and realization.",
        "maturity": "The method is experimentally mature, with clock performance and applications advancing over many years.",
        "uncertainties": [
          "The precise division between independent invention, realization, and subsequent performance milestones needs careful historical review."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "The prediction and experimental realization of time-reversal-invariant topological insulators established a major new phase of matter and a lasting direction in condensed matter physics.",
        "attribution": "Kane and Mele supplied the theoretical prediction; Molenkamp's experiments provided an early decisive realization of the quantum spin Hall effect.",
        "maturity": "The phase and its characteristic behavior have been confirmed in multiple materials and experiments.",
        "uncertainties": [
          "The relationship between the early quantum spin Hall realization and later three-dimensional topological insulators complicates the scope of a single prize."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B008",
      "proposed_laureates": [
        "Peter F. Moulton",
        "Ursula Keller",
        "Wilson Sibbett"
      ],
      "assessment": {
        "nobel_worthiness": "Titanium-sapphire lasers and practical passive mode-locking made broadly useful femtosecond sources possible, enabling precise studies of ultrafast processes.",
        "attribution": "Moulton's laser medium and the mode-locking advances associated with Keller and Sibbett form complementary parts of the development described.",
        "maturity": "The technology has been extensively used and its scientific value is well established.",
        "uncertainties": [
          "The bundled discovery joins distinct developments; priority and the boundaries of each person's contribution require close verification."
        ]
      }
    },
